/**
 * `site/static/money.js` against the reference engine.
 *
 * `fixtures/money_cases.json` is `cost.meter_price` and `cost.risk_dollars` over
 * every distinct `hour_rates` list and every `(parse, snap)` confidence pair the
 * database holds, so the integer and `BigInt` arithmetic here is checked against
 * `Decimal` on the inputs that actually ship. Regenerated by
 * `harness/make_money_fixtures.py`.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { centsToString, decimalStringToScaled, parseCents, riskCents } from "../static/money.js";
import { meterPrice } from "../static/engine/cost.js";

const FIXTURE = JSON.parse(
  readFileSync(fileURLToPath(new URL("./fixtures/money_cases.json", import.meta.url)), "utf-8"),
);

test("meter prices match Decimal on every rate list in the database", () => {
  for (const item of FIXTURE.meter) {
    const where = `${JSON.stringify(item.hour_rates)} x ${item.charged_minutes} min`;
    if (item.price === null) {
      // An empty rate list is a price we do not know, not a free spot.
      assert.throws(() => meterPrice(item.hour_rates, item.charged_minutes), where);
      continue;
    }
    const cents = meterPrice(item.hour_rates, item.charged_minutes);
    assert.strictEqual(centsToString(cents), item.price, where);
  }
});

test("risk matches Decimal on every confidence pair in the database", () => {
  const standard = Number(FIXTURE.fines.standard);
  const hydrant = Number(FIXTURE.fines.hydrant);
  for (const item of FIXTURE.risk) {
    const where = `${item.parse_confidence}/${item.snap_confidence}`;
    assert.strictEqual(
      centsToString(riskCents(item.parse_confidence, item.snap_confidence, standard)),
      item.standard,
      where,
    );
    assert.strictEqual(
      centsToString(riskCents(item.parse_confidence, item.snap_confidence, hydrant)),
      item.hydrant,
      where,
    );
  }
});

test("parse_cents reads the two-decimal strings the pack carries", () => {
  assert.strictEqual(parseCents("8.25"), 825);
  assert.strictEqual(parseCents("5"), 500);
  assert.strictEqual(parseCents("0.5"), 50);
  assert.strictEqual(parseCents("0.05"), 5);
  assert.strictEqual(parseCents("-1.25"), -125);
});

test("a rate with more than two decimals is refused", () => {
  assert.throws(() => parseCents("1.234"), /two places/);
  assert.throws(() => parseCents("free"), /two places/);
});

test("cents_to_string always writes two decimal places", () => {
  assert.strictEqual(centsToString(0), "0.00");
  assert.strictEqual(centsToString(5), "0.05");
  assert.strictEqual(centsToString(1250), "12.50");
  assert.strictEqual(centsToString(100000), "1000.00");
  assert.strictEqual(centsToString(-325), "-3.25");
});

test("both spellings of a small double parse to the same exact decimal", () => {
  // JavaScript writes 5e-05 as "0.00005" and Python's repr writes "5e-05";
  // the digits are the same shortest round-trip, so the value has to be too.
  assert.deepStrictEqual(decimalStringToScaled("0.00005"), { value: 5n, scale: 5 });
  assert.deepStrictEqual(decimalStringToScaled("5e-05"), { value: 5n, scale: 5 });
  assert.deepStrictEqual(decimalStringToScaled("1.5e2"), { value: 150n, scale: 0 });
  assert.deepStrictEqual(decimalStringToScaled("65"), { value: 65n, scale: 0 });
});

test("risk rounds a half cent away from zero, as Decimal does", () => {
  // Confidences whose doubt is exact in binary, so the product really lands on
  // half a cent: 0.125 * 65 = 8.125 dollars and 0.03125 * 65 = 2.03125.
  assert.strictEqual(riskCents(0.75, 1.0, 65), 813);
  assert.strictEqual(riskCents(0.9375, 1.0, 65), 203);
});

test("certainty costs nothing and total doubt costs half the fine", () => {
  assert.strictEqual(riskCents(1.0, 1.0, 65), 0);
  assert.strictEqual(riskCents(0.0, 1.0, 65), 3250);
  assert.strictEqual(riskCents(1.0, 0.0, 115), 5750);
});
